(() => {
  const canvas = document.querySelector('#arena');
  const ctx = canvas.getContext('2d');
  const $ = (s) => document.querySelector(s);
  const ui = { playerHealth: $('.player-health'), enemyHealth: $('.enemy-health'), playerEnergy: $('.player-energy'), enemyEnergy: $('.enemy-energy'), timer: $('#timer'), state: $('#matchState'), callout: $('#callout'), combo: $('#combo'), help: $('#helpPanel'), result: $('#result'), resultTitle: $('#resultTitle'), resultSub: $('#resultSub') };
  let W = 0, H = 0, dpr = 1, last = 0, elapsed = 0, gameState = 'intro', timeLeft = 99, hitStop = 0, shake = 0, comboTimer = 0, comboCount = 0, audioOn = true, audioCtx = null;
  const keys = new Set(), particles = [], projectiles = [], sparks = [];
  const player = makeFighter('AKARI', -0.55, '#ff546b', '#a42e73', 'player');
  const enemy = makeFighter('KAIRO', 0.55, '#54e8ff', '#284ba5', 'enemy');
  function makeFighter(name, x, primary, secondary, side) { return { name, x, z: side === 'player' ? .64 : .69, vx: 0, vy: 0, health: 100, energy: 15, primary, secondary, side, facing: side === 'player' ? 1 : -1, action: 'idle', actionT: 0, actionDur: 0, hitDone: false, hurtT: 0, guard: false, grounded: true, jumpT: 0, aiWait: 1.1, wins: 0 }; }
  function resize() { const rect = canvas.getBoundingClientRect(); dpr = Math.min(window.devicePixelRatio || 1, 2); W = rect.width; H = rect.height; canvas.width = Math.round(W * dpr); canvas.height = Math.round(H * dpr); ctx.setTransform(dpr, 0, 0, dpr, 0, 0); }
  window.addEventListener('resize', resize); resize();
  function rand(a,b){return a+Math.random()*(b-a)}
  function clamp(v,a,b){return Math.max(a,Math.min(b,v))}
  function sound(freq=220, duration=.07, type='sine', volume=.035) { if(!audioOn)return; try { audioCtx ||= new (window.AudioContext||window.webkitAudioContext)(); const o=audioCtx.createOscillator(), g=audioCtx.createGain(); o.type=type;o.frequency.setValueAtTime(freq,audioCtx.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(35,freq*.48),audioCtx.currentTime+duration);g.gain.setValueAtTime(volume,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration); } catch(_){} }
  function setHealth(f,v){ f.health=clamp(v,0,100); (f===player?ui.playerHealth:ui.enemyHealth).style.width=f.health+'%'; }
  function setEnergy(f,v){ f.energy=clamp(v,0,100); (f===player?ui.playerEnergy:ui.enemyEnergy).style.width=f.energy+'%'; }
  function beginFight(){ if(gameState==='fight')return; if(gameState==='over')resetMatch(); ui.help.classList.remove('open'); ui.result.classList.remove('show'); gameState='fight';timeLeft=99;ui.timer.textContent='99';ui.state.textContent='FIGHT!';ui.callout.querySelector('span').textContent='FIGHT!';showCallout(); sound(520,.16,'triangle',.05); }
  function showCallout(){ui.callout.classList.remove('show');void ui.callout.offsetWidth;ui.callout.classList.add('show')}
  function resetMatch(){for(const f of [player,enemy]){f.x=f.side==='player'?-0.55:.55;f.vx=f.vy=0;f.health=100;f.energy=15;f.action='idle';f.actionT=0;f.hurtT=0;f.guard=false;f.grounded=true;f.hitDone=false;f.aiWait=1.2;}setHealth(player,100);setHealth(enemy,100);setEnergy(player,15);setEnergy(enemy,15);timeLeft=99;comboCount=0;ui.combo.style.opacity=0;particles.length=projectiles.length=sparks.length=0;}
  function attack(f,type){ if(gameState!=='fight'||f.hurtT>0||f.action==='attack'||f.action==='special'||f.action==='dash')return; if(type==='special'&&f.energy<35){f.action='guard';f.actionT=.26;return;} if(type==='special')setEnergy(f,f.energy-35); const durations={light:.38,heavy:.62,special:.78};f.action=type==='special'?'special':'attack';f.attackType=type;f.actionT=durations[type];f.actionDur=durations[type];f.hitDone=false;f.guard=false;sound(type==='light'?330:type==='heavy'?145:440,type==='special'?.16:.09,type==='heavy'?'sawtooth':'triangle',.035); if(type==='special'){projectiles.push({owner:f,x:f.x+f.facing*.12,z:f.z,life:1.25,speed:f.facing*1.95,color:f.primary,hit:false});for(let i=0;i<16;i++)particles.push({x:f.x+f.facing*.16,y:-.9,z:f.z,vx:rand(-.45,.45),vy:rand(-.7,.3),life:rand(.3,.65),color:f.primary,size:rand(2,7)});}}
  function jump(f){if(f.grounded&&gameState==='fight'){f.vy=4.2;f.grounded=false;f.action='jump';f.actionT=.5;sound(180,.07,'sine',.02)}}
  function dash(f,dir){if(gameState!=='fight'||f.action==='dash')return;f.action='dash';f.actionT=.23;f.vx=dir*2.35;f.guard=false;for(let i=0;i<7;i++)particles.push({x:f.x,y:-.15,z:f.z,vx:-dir*rand(.12,.6),vy:-rand(0,.35),life:rand(.2,.45),color:f.primary,size:rand(3,8)});}
  function startGuard(f,on){if(gameState==='fight'&&f.hurtT<=0&&f.action!=='attack'&&f.action!=='special'&&f.action!=='dash'){f.guard=on;if(on)f.action='guard';else if(f.action==='guard')f.action='idle';}}
  function playerInput(){if(gameState!=='fight')return;let dir=(keys.has('d')?1:0)-(keys.has('a')?1:0);if(dir){player.facing=dir>0?1:-1;if(player.action==='idle'||player.action==='walk'||player.action==='guard'){player.vx=dir*1.05;if(!player.guard)player.action='walk';}}else if(player.action==='walk'){player.action='idle';player.vx=0;}if(keys.has('s'))startGuard(player,true);else if(player.guard)startGuard(player,false);}
  window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','arrowleft','arrowright','arrowup'].includes(k))e.preventDefault();if(keys.has(k))return;keys.add(k);if(k==='enter'){beginFight();return;}if(k==='escape'){ui.help.classList.toggle('open');return;}if(k==='w'||k==='arrowup')jump(player);if(k==='j')attack(player,'light');if(k==='k')attack(player,'heavy');if(k==='l')attack(player,'special');if(k===' '||k==='shift')dash(player,player.facing);});
  window.addEventListener('keyup',e=>{const k=e.key.toLowerCase();keys.delete(k);if(k==='s')startGuard(player,false);});
  document.querySelectorAll('[data-key]').forEach(btn=>{const k=btn.dataset.key;const down=e=>{e.preventDefault();keys.add(k);if(k==='j'||k==='k'||k==='l')attack(player,k==='j'?'light':k==='k'?'heavy':'special');};const up=e=>{e.preventDefault();keys.delete(k);if(k==='s')startGuard(player,false)};btn.addEventListener('pointerdown',down);btn.addEventListener('pointerup',up);btn.addEventListener('pointercancel',up);btn.addEventListener('pointerleave',up)});
  $('#helpBtn').addEventListener('click',()=>ui.help.classList.add('open'));$('#closeHelp').addEventListener('click',()=>ui.help.classList.remove('open'));$('#startHelp').addEventListener('click',beginFight);$('#rematch').addEventListener('click',()=>{resetMatch();beginFight()});$('#soundBtn').addEventListener('click',()=>{audioOn=!audioOn;$('#soundBtn').innerHTML=audioOn?'♫ <span>SOUND ON</span>':'♫ <span>SOUND OFF</span>';});

function update(dt){elapsed+=dt;if(gameState==='fight'){timeLeft-=dt;if(timeLeft<=0){timeLeft=0;finish(player.health>=enemy.health?'player':'enemy','TIME UP');}ui.timer.textContent=String(Math.ceil(timeLeft)).padStart(2,'0');playerInput();updateAI(dt);for(const f of [player,enemy])updateFighter(f,dt);resolveClash();updateProjectiles(dt);updateParticles(dt);}else{for(const f of [player,enemy]){f.x+=Math.sin(elapsed*1.1+(f===player?0:1))*dt*.025;f.facing=f===player?1:-1;}updateParticles(dt);}if(comboTimer>0){comboTimer-=dt;if(comboTimer<=0){ui.combo.style.opacity=0;comboCount=0;}}if(hitStop>0)hitStop=Math.max(0,hitStop-dt);if(shake>0)shake=Math.max(0,shake-dt*28);}
function updateAI(dt){if(gameState!=='fight'||enemy.hurtT>0||enemy.action==='attack'||enemy.action==='special'||enemy.action==='dash')return;const dx=player.x-enemy.x,dist=Math.abs(dx);enemy.facing=dx<0?-1:1;enemy.aiWait-=dt;if(dist>0.42){enemy.guard=false;enemy.action='walk';enemy.vx=Math.sign(dx)*.72;}else{enemy.vx=0;if(enemy.action==='walk')enemy.action='idle';if(enemy.aiWait<=0){if(player.action==='attack'&&Math.random()<.42){enemy.guard=true;enemy.action='guard';enemy.aiWait=rand(.35,.8);}else{enemy.guard=false;const roll=Math.random();if(enemy.energy>=35&&roll<.2)attack(enemy,'special');else attack(enemy,roll<.67?'light':'heavy');enemy.aiWait=rand(.55,1.15);}}else if(player.action==='attack'&&dist<.5&&Math.random()<dt*1.2){enemy.guard=true;enemy.action='guard';}}}
function updateFighter(f,dt){if(f.hurtT>0){f.hurtT-=dt;if(f.hurtT<=0&&f.action==='hurt')f.action='idle';}if(f.actionT>0){f.actionT-=dt;if(f.actionT<=0){if(f.action==='attack'||f.action==='special'||f.action==='dash'||f.action==='guard'||f.action==='hurt'||f.action==='jump')f.action='idle';f.guard=false;}}if(f.action!=='dash'&&f.action!=='hurt')f.x+=f.vx*dt;else f.x+=f.vx*dt;f.vx*=Math.pow(.001,dt);f.x=clamp(f.x,-1.23,1.23);if(!f.grounded){f.vy-=10.8*dt;f.jumpHeight=Math.max(0,(f.jumpHeight||0)+f.vy*dt);if(f.jumpHeight<=0){f.jumpHeight=0;f.vy=0;f.grounded=true;f.action='idle';}}else f.jumpHeight=0;}
function resolveClash(){for(const f of [player,enemy]){if((f.action==='attack'||f.action==='special')&&!f.hitDone){const prog=1-f.actionT/f.actionDur, active=prog>(f.attackType==='light'?.36:.42)&&prog<(f.attackType==='light'?.75:.78);if(active){const foe=f===player?enemy:player;const dist=Math.abs(f.x-foe.x);if(dist<(f.attackType==='light'?.48:f.attackType==='heavy'?.58:.62)&&Math.abs(f.z-foe.z)<.25){f.hitDone=true;hit(f,foe,f.attackType);}}}}}
function hit(from,to,type){const blocked=to.guard&&from.x>to.x===false?false:to.guard&&((from.x<to.x&&to.facing<0)||(from.x>to.x&&to.facing>0));const base=type==='light'?7:type==='heavy'?13:18;let damage=blocked?Math.ceil(base*.16):base;setHealth(to,to.health-damage);setEnergy(from,from.energy+(blocked?7:10));setEnergy(to,to.energy+(blocked?5:3));to.hurtT=blocked?.14:.29;to.action=blocked?'guard':'hurt';to.actionT=to.hurtT;to.vx=(to.x>from.x?1:-1)*(blocked?.14:type==='heavy'?.62:.35);hitStop=blocked?.045:.085;shake=blocked?3:damage>12?11:6;const sx=(W/2+((from.x+to.x)/2)*W*.33),sy=groundY((from.z+to.z)/2)-85;burst(sx,sy,blocked?'#aaf4ff':from.primary,blocked?11:18);sound(blocked?270:110+damage*8,.12,blocked?'triangle':'sawtooth',.045);if(from===player&&!blocked){comboCount++;comboTimer=1.35;ui.combo.innerHTML=`${comboCount} HIT <small>RIFT COMBO</small>`;ui.combo.style.opacity=1;}if(to.health<=0)finish(from===player?'player':'enemy','K.O.');}
function burst(x,y,color,n){for(let i=0;i<n;i++){const a=rand(0,Math.PI*2),speed=rand(55,280);sparks.push({x,y,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,life:rand(.16,.42),max:.42,color,size:rand(1,4)});}for(let i=0;i<8;i++)particles.push({sx:x,sy:y,screen:true,vx:rand(-100,100),vy:rand(-100,80),life:rand(.16,.38),color,size:rand(2,7)});}
function updateProjectiles(dt){for(let i=projectiles.length-1;i>=0;i--){const p=projectiles[i];p.x+=p.speed*dt;p.life-=dt;const foe=p.owner===player?enemy:player;if(!p.hit&&Math.abs(p.x-foe.x)<.17&&Math.abs(p.z-foe.z)<.3){p.hit=true;hit(p.owner,foe,'special');}if(p.life<=0||Math.abs(p.x)>1.7)projectiles.splice(i,1);}}
